// Table-driven conformance test for the H0WS handshake / HTTP / connection-lifecycle family.
// Reads table.json (generated by gen_table.py from the decompiled listings) and drives every
// assertion from it, then self-checks member coverage (>=2 assertions each) and the
// effective-coverage figure computed from buckets.tsv.
#include "impl.h"

#include <cctype>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

// ----------------------------------------------------------------- minimal JSON
struct J {
  enum Type { Null, Bool, Num, Str, Arr, Obj } t = Null;
  bool b = false;
  double n = 0;
  std::string s;
  std::vector<J> a;
  std::vector<std::pair<std::string, J>> o;
  const J& operator[](const std::string& k) const {
    static J nul;
    for (auto& kv : o)
      if (kv.first == k) return kv.second;
    return nul;
  }
};

struct Parser {
  std::string src;
  std::size_t i = 0;
  explicit Parser(std::string s) : src(std::move(s)) {}
  void ws() {
    while (i < src.size() && (src[i] == ' ' || src[i] == '\n' || src[i] == '\r' || src[i] == '\t')) ++i;
  }
  J value() {
    ws();
    J v;
    if (i >= src.size()) return v;
    char c = src[i];
    if (c == '{') {
      ++i; v.t = J::Obj; ws();
      if (src[i] == '}') { ++i; return v; }
      while (true) {
        ws(); J k = value(); ws();
        if (src[i] == ':') ++i;
        J val = value();
        v.o.emplace_back(k.s, val);
        ws();
        if (src[i] == ',') { ++i; continue; }
        if (src[i] == '}') { ++i; break; }
        break;
      }
      return v;
    }
    if (c == '[') {
      ++i; v.t = J::Arr; ws();
      if (src[i] == ']') { ++i; return v; }
      while (true) {
        v.a.push_back(value());
        ws();
        if (src[i] == ',') { ++i; continue; }
        if (src[i] == ']') { ++i; break; }
        break;
      }
      return v;
    }
    if (c == '"') {
      ++i; v.t = J::Str;
      while (i < src.size() && src[i] != '"') {
        char ch = src[i++];
        if (ch == '\\' && i < src.size()) {
          char e = src[i++];
          switch (e) {
            case 'n': v.s.push_back('\n'); break;
            case 'r': v.s.push_back('\r'); break;
            case 't': v.s.push_back('\t'); break;
            case 'u': {
              unsigned code = 0;
              for (int k = 0; k < 4 && i < src.size(); ++k) {
                char h = src[i++];
                code = code * 16 + (h <= '9' ? h - '0' : (std::tolower(h) - 'a' + 10));
              }
              if (code < 0x80) v.s.push_back(char(code));
              else v.s.push_back('?');
              break;
            }
            default: v.s.push_back(e);
          }
        } else {
          v.s.push_back(ch);
        }
      }
      if (i < src.size()) ++i;
      return v;
    }
    if (src.compare(i, 4, "true") == 0) { i += 4; v.t = J::Bool; v.b = true; return v; }
    if (src.compare(i, 5, "false") == 0) { i += 5; v.t = J::Bool; v.b = false; return v; }
    if (src.compare(i, 4, "null") == 0) { i += 4; return v; }
    std::size_t st = i;
    while (i < src.size() && (std::isdigit((unsigned char)src[i]) || src[i] == '-' || src[i] == '+' ||
                              src[i] == '.' || src[i] == 'e' || src[i] == 'E'))
      ++i;
    v.t = J::Num;
    v.n = std::strtod(src.substr(st, i - st).c_str(), nullptr);
    return v;
  }
};

// ----------------------------------------------------------------- harness
static int g_total = 0;
static int g_fail = 0;
static std::map<std::string, int> g_per_member;

static void check(bool ok, const std::string& member, const std::string& what) {
  ++g_total;
  ++g_per_member[member];
  if (!ok) {
    ++g_fail;
    std::printf("FAIL %-4s %s\n", member.c_str(), what.c_str());
  }
}

static std::string hex_of(const std::array<std::uint8_t, 20>& d) {
  static const char* H = "0123456789abcdef";
  std::string s;
  for (auto c : d) { s.push_back(H[c >> 4]); s.push_back(H[c & 15]); }
  return s;
}

static std::string bytes_from_hex(const std::string& h) {
  std::string out;
  for (std::size_t i = 0; i + 1 < h.size(); i += 2) {
    auto v = [](char c) { return c <= '9' ? c - '0' : (std::tolower(c) - 'a' + 10); };
    out.push_back(char(v(h[i]) * 16 + v(h[i + 1])));
  }
  return out;
}

static std::string kind_name(h0ws::RecvKind k) {
  switch (k) {
    case h0ws::RecvKind::kDelivered: return "Delivered";
    case h0ws::RecvKind::kAgain: return "Again";
    case h0ws::RecvKind::kEof: return "Eof";
    case h0ws::RecvKind::kFatal: return "Fatal";
    case h0ws::RecvKind::kBogus: return "Bogus";
  }
  return "?";
}

static std::string kind_name(h0ws::SendKind k) {
  switch (k) {
    case h0ws::SendKind::kBogus: return "Bogus";
    case h0ws::SendKind::kDrainAndShutdown: return "DrainAndShutdown";
    case h0ws::SendKind::kAgain: return "Again";
    case h0ws::SendKind::kPartial: return "Partial";
    case h0ws::SendKind::kComplete: return "Complete";
  }
  return "?";
}

int main() {
  std::ifstream in("table.json", std::ios::binary);
  if (!in) {
    std::printf("FATAL: cannot open table.json (run from the handshake_family directory)\n");
    return 2;
  }
  std::stringstream ss;
  ss << in.rdbuf();
  Parser p(ss.str());
  J root = p.value();
  const J& tables = root["tables"];
  const J& members = root["members"];

  using namespace h0ws;

  // ---- T1 base64 ------------------------------------------------------------
  for (const J& r : tables["T1_base64"].a) {
    std::string in = bytes_from_hex(r["hex"].s);
    std::string got = base64_encode(reinterpret_cast<const std::uint8_t*>(in.data()), in.size());
    check(got == r["out"].s, "M01", "T1 " + r["id"].s + " base64(" + r["hex"].s + ")");
  }

  // ---- T2 upgrade request ---------------------------------------------------
  for (const J& r : tables["T2_request"].a) {
    std::string req = upgrade_request(r["key"].s);
    check(req.size() == std::size_t(r["len"].n), "M01", "T2 " + r["id"].s + " request length");
    check(req.compare(0, r["prefix"].s.size(), r["prefix"].s) == 0, "M01",
          "T2 " + r["id"].s + " request-line prefix");
    check(req.find(r["key"].s) == std::size_t(r["head_off"].n), "M01",
          "T2 " + r["id"].s + " key offset");
    check(req.size() >= 4 && req.compare(req.size() - 4, 4, r["tail"].s) == 0, "M01",
          "T2 " + r["id"].s + " trailing CRLFCRLF");
  }
  {
    // M01 extras: the nonce is constant, and the request carries no Host header.
    check(client_key() == "AAAAAAAAAAAAAAAAAAAAAA==", "M01", "M01 zero nonce -> constant key");
    check(client_key().size() == kKeyChars, "M01", "M01 key is 24 base64 chars");
    std::string req = upgrade_request(client_key());
    check(req.find("Host:") == std::string::npos, "M01", "M01 no Host header (non-RFC request)");
    check(std::string(kBase64Alphabet).size() == 65, "M01", "M01 alphabet incl. '=' pad is 65 chars");
    check(req.find("Sec-WebSocket-Version: 13") != std::string::npos, "M01",
          "M01 sends version 13");
    check(req.find("Sec-WebSocket-Extensions: permessage-deflate") != std::string::npos, "M01",
          "M01 always offers permessage-deflate");
  }

  // ---- T3 response scan -----------------------------------------------------
  for (const J& r : tables["T3_response_scan"].a) {
    RespScan s = scan_upgrade_response(r["buf"].s.data(), r["buf"].s.size());
    check(s.deflate == r["deflate"].b, "M03", "T3 " + r["id"].s + " deflate flag");
    check(s.head_end == std::size_t(r["head_end"].n), "M03", "T3 " + r["id"].s + " head_end");
  }
  {
    check(std::string(kDeflateNeedle).size() == kNeedleLen, "M03", "M03 needle length 18");
    // The head is consumed, the rest of the buffer survives (memmove at 0x10dd9e).
    std::string buf = "HTTP/1.1 101 X\r\n\r\nPAYLOAD";
    RespScan s = scan_upgrade_response(buf.data(), buf.size());
    std::string rest = buf.substr(s.head_end);
    check(rest == "PAYLOAD", "M03", "M03 keeps bytes after the head");
    check(s.head_end == 18, "M03", "M03 head_end == idx(CRLFCRLF)+4");
  }

  // ---- T4 sha1 --------------------------------------------------------------
  for (const J& r : tables["T4_sha1"].a) {
    auto d = sha1(r["input"].s.data(), r["input"].s.size());
    check(hex_of(d) == r["hex"].s, "M04", "T4 " + r["id"].s + " sha1 digest");
  }
  {
    check(accept_key("dGhlIHNhbXBsZSBub25jZQ==") == "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=", "M04",
          "M04 RFC6455 sample accept");
    check(accept_key(client_key()) == "ICX+Yqv66kxgM0FcWaLWlFLwTAI=", "M04",
          "M04 accept for the constant key");
    check(accept_key(client_key()).size() == 28, "M04", "M04 accept is 28 chars");
  }

  // ---- T5 conn ctor flags ---------------------------------------------------
  {
    ConnFlags f = conn_ctor_flags();
    for (const J& r : tables["T5_conn_ctor_flags"].a) {
      bool got = r["name"].s == "recv_open"    ? f.recv_open
                 : r["name"].s == "send_open"  ? f.send_open
                 : r["name"].s == "send_armed" ? f.send_armed
                                               : f.read_armed;
      check(got == r["value"].b, "M08", "T5 " + r["id"].s + " " + r["name"].s);
    }
  }

  // ---- T6 recv_step ---------------------------------------------------------
  for (const J& r : tables["T6_recv_step"].a) {
    ConnFlags f;
    f.read_armed = r["armed"].b;
    f.recv_open = f.send_open = true;
    RecvStep s = recv_step(f, long(r["n"].n), int(r["err"].n));
    check(kind_name(s.kind) == r["kind"].s, "M10", "T6 " + r["id"].s + " kind");
    check(s.clear_recv_open == r["clear_recv"].b, "M10", "T6 " + r["id"].s + " clear recv_open");
    check(s.clear_send_open == r["clear_send"].b, "M10", "T6 " + r["id"].s + " clear send_open");
    check(s.clear_read_armed == r["clear_armed"].b, "M10", "T6 " + r["id"].s + " clear read_armed");
    check(s.fire_on_read == r["fire"].b, "M10", "T6 " + r["id"].s + " fire on_read");
  }
  check(kRecvChunk == 32768, "M10", "M10 read chunk is 0x8000");

  // ---- T7 send_step ---------------------------------------------------------
  for (const J& r : tables["T7_send_step"].a) {
    SendStep s = send_step(r["armed"].b, r["pending"].b, std::size_t(r["queued"].n),
                           long(r["n"].n), int(r["err"].n));
    check(kind_name(s.kind) == r["kind"].s, "M11", "T7 " + r["id"].s + " kind");
    check(s.clear_send_open == r["clear_open"].b, "M11", "T7 " + r["id"].s + " clear send_open");
    check(s.clear_send_armed == r["clear_armed"].b, "M11", "T7 " + r["id"].s + " clear send_armed");
    check(s.shutdown_wr == r["shutdown"].b, "M11", "T7 " + r["id"].s + " shutdown(SHUT_WR)");
    check(s.fire_write_cb == r["fire"].b, "M11", "T7 " + r["id"].s + " write callback");
    check(s.unsent == std::size_t(r["unsent"].n), "M11", "T7 " + r["id"].s + " unsent bytes");
  }

  // ---- T8 client_poll -------------------------------------------------------
  for (const J& r : tables["T8_client_poll"].a) {
    ConnFlags f;
    f.recv_open = r["recv_open"].b;
    f.send_open = r["send_open"].b;
    ClientPoll s = client_poll(ClientState(int(r["state"].n)), int(r["events"].n),
                               int(r["so_error"].n), r["fd_match"].b, f);
    check(int(s.next) == int(r["next"].n), "M12", "T8 " + r["id"].s + " next state");
    check(s.cb == int(r["cb"].n), "M12", "T8 " + r["id"].s + " callback id");
    check(s.reap == r["reap"].b, "M12", "T8 " + r["id"].s + " reap");
    check(s.call_send == r["call_send"].b, "M12", "T8 " + r["id"].s + " send_proc");
    check(s.call_recv == r["call_recv"].b, "M12", "T8 " + r["id"].s + " recv_proc");
  }

  // ---- T9 server reap -------------------------------------------------------
  for (const J& r : tables["T9_server_reap"].a) {
    ConnFlags f;
    f.recv_open = r["recv_open"].b;
    f.send_open = r["send_open"].b;
    check(server_should_reap(f) == r["reap"].b, "M13", "T9 " + r["id"].s + " reap");
  }
  {
    ServerDispatch d = server_dispatch(3);
    check(d.call_send && d.call_recv && d.send_before_recv, "M13",
          "M13 send_proc runs before recv_proc");
    ServerDispatch d2 = server_dispatch(1);
    check(d2.call_recv && !d2.call_send, "M13", "M13 EPOLLIN only -> recv only");
  }

  // ---- T10 loop interest ----------------------------------------------------
  for (const J& r : tables["T10_loop_interest"].a) {
    check(loop_interest_word(r["in"].b, r["out"].b) == int(r["word"].n), "M16",
          "T10 " + r["id"].s + " epoll event word");
  }
  {
    check(loop_timeout_ms(1000000) == 1000, "M16", "M16 default timeout 1000000us -> 1000ms");
    check(kEpollMaxEvents == 1, "M16", "M16 epoll_wait maxevents == 1");
    check(kEpollCloexec == 0x80000, "M16", "M16 epoll_create1(EPOLL_CLOEXEC)");
    check(loop_starts_running(), "M16", "M16 EventLoop2 ctor sets running=1");
  }

  // ---- T11 api transport ----------------------------------------------------
  for (const J& r : tables["T11_api_transport"].a) {
    check(api_connect_plan(r["addr"].s).is_unix == r["unix"].b, "M17",
          "T11 " + r["id"].s + " transport choice");
  }
  {
    ApiConnectPlan cp = api_connect_plan("127.0.0.1");
    check(cp.run_loop_inline, "M17", "M17 connect() runs the loop inline");
    check(cp.return_handle_zero_on_loop_ok, "M17", "M17 loop rc 0 -> handle becomes NULL");
    check(str_arg_kind(false) == StrArgKind::kUnicode, "M17", "M17 py3 str arg -> PyUnicode_AsUTF8");
    check(str_arg_kind(true) == StrArgKind::kBytes, "M17", "M17 py3 bytes arg -> PyBytes path");
  }

  // ---- T12 exit waves -------------------------------------------------------
  for (const J& r : tables["T12_exit_waves"].a) {
    ExitPlan e = wsconn_exit_plan(r["recv_flag"].b, r["send_flag"].b);
    check(e.warn_recv_flag == r["warn_recv"].b, "M14", "T12 " + r["id"].s + " recv_flag warning");
    check(e.warn_send_flag == r["warn_send"].b, "M14", "T12 " + r["id"].s + " send_flag warning");
    check(e.callbacks_replaced == int(r["callbacks"].n), "M14",
          "T12 " + r["id"].s + " callbacks replaced");
    check(e.set_recv_flag && e.set_send_flag && e.drop_pending, "M14",
          "T12 " + r["id"].s + " flags set + pending dropped");
  }

  // ---- remaining member assertions (no table rows: single-shape facts) ------
  {
    ClientPlan p = plan_tcp_client();
    check(p.family == 2 && p.type == 1 && p.proto == 0, "M06", "M06 socket(AF_INET, SOCK_STREAM, 0)");
    check(p.sockopt_level == 6 && p.sockopt_opt == 1 && p.sockopt_val == 1, "M06",
          "M06 setsockopt(IPPROTO_TCP, TCP_NODELAY, 1)");
    check(p.nonblock && p.cloexec, "M06", "M06 nonblock + cloexec");
    check(p.fail_state == 2, "M06", "M06 hard connect failure -> state 2");
    check(p.connect_mask == 0x10, "M06", "M06 connect(..., 16) sockaddr_in length");
    check(classify_connect(0, 0) == ConnectOutcome::kConnectedNow, "M06", "M06 rc 0 -> connected");
    check(classify_connect(-1, kEinprogress) == ConnectOutcome::kInProgress, "M06",
          "M06 EINPROGRESS(115) -> async");
    check(classify_connect(-1, 111) == ConnectOutcome::kFailed, "M06", "M06 ECONNREFUSED -> fail");
  }
  {
    FdClientPlan f = fd_client_plan();
    check(!f.opens_socket && !f.probes_connect, "M07", "M07 adopts fd, no socket()/connect()");
    check(f.state_connected, "M07", "M07 state := 1 (already connected)");
    check(f.empty_host && f.empty_name, "M07", "M07 conn built with empty host/name");
    check(f.calls_on_conn_sync, "M07", "M07 on_conn fires synchronously");
  }
  {
    DtorPlan d = tcpconn_dtor_plan();
    check(d.close_fd, "M09", "M09 close(fd)");
    check(d.listener_trees_erased == 3, "M09", "M09 erases 3 fd->conn trees");
    check(d.buffers_freed == 1, "M09", "M09 frees the pending buffer");
    check(!d.end_zlib, "M09", "M09 zlib untouched");
  }
  {
    check(!wsconn_dtor_plan(false).end_zlib, "M15", "M15 no zlib when not negotiated");
    check(wsconn_dtor_plan(true).end_zlib, "M15", "M15 inflateEnd+deflateEnd when negotiated");
    check(wsconn_dtor_plan(true).buffers_freed == 3, "M15", "M15 frees 3 buffers");
    check(!wsconn_dtor_plan(true).close_fd, "M15", "M15 does not close the fd");
  }
  {
    // M02: the wait closure is exactly recv_pat("\r\n\r\n") (frames_family M01 alias).
    check(std::string(kHeadNeedle).size() == kHeadLen, "M02", "M02 head needle is 4 bytes");
    RespScan s = scan_upgrade_response("\r\n\r\n", 4);
    check(s.head_end == 4, "M02", "M02 immediate head -> consume 4");
    RespScan s2 = scan_upgrade_response("A\r\n\r\nB\r\n\r\n", 10);
    check(s2.head_end == 5, "M02", "M02 first head wins");
    check(scan_upgrade_response("XXXX", 4).head_end == 4, "M02",
          "M02 no head -> sentinel n (recv_pat would not fire)");
  }
  {
    // M05 appendf
    std::string b;
    buffer_appendf(b, "GET %s HTTP/1.1\r\n", std::string("/"));
    check(b == "GET / HTTP/1.1\r\n", "M05", "M05 single append");
    buffer_appendf(b, "%s", std::string("X"));
    check(b == "GET / HTTP/1.1\r\nX", "M05", "M05 second append uses current size as offset");
    check(b.size() == std::strlen(b.c_str()), "M05", "M05 trailing NUL trimmed");
    check(b.find('\0') == std::string::npos, "M05", "M05 no embedded NUL");
  }
  {
    // M18 disconnect
    ApiDisconnectPlan a = api_disconnect_plan(false, false);
    check(!a.closes_wsconn && !a.runs_loop, "M18", "M18 NULL handle -> no close, no loop");
    ApiDisconnectPlan b = api_disconnect_plan(true, false);
    check(!b.closes_wsconn && b.runs_loop && b.destroys_loop, "M18",
          "M18 handle without WSConn -> run+drain loop");
    ApiDisconnectPlan c = api_disconnect_plan(true, true);
    check(c.closes_wsconn && c.runs_loop && c.destroys_loop, "M18",
          "M18 handle+WSConn -> close then drain");
    check(c.returns == 0, "M18", "M18 returns integer 0");
  }

  // ---- C01: every member must have >= 2 assertions -------------------------
  int members_seen = 0;
  for (const J& m : members.a) {
    const std::string id = m["id"].s;
    ++members_seen;
    int got = g_per_member[id];
    check(got >= 2, "C01", "C01 " + id + " has >=2 assertions (got " + std::to_string(got) + ")");
    check(got >= int(m["asserts"].n), "C01",
          "C01 " + id + " meets declared assertion count " + std::to_string(int(m["asserts"].n)));
  }
  check(members_seen == 18, "C01", "C01 member count == 18");

  // ---- C04: cross-build offsets -------------------------------------------
  int same = 0;
  for (const J& m : members.a) {
    unsigned long long a3 = std::strtoull(m["py3"].s.c_str(), nullptr, 16);
    unsigned long long a2 = std::strtoull(m["py2"].s.c_str(), nullptr, 16);
    check(a3 - a2 == (unsigned long long)m["delta"].n, "C04",
          "C04 " + m["id"].s + " py3-py2 == " + std::to_string(int(m["delta"].n)));
    if (m["same"].b) ++same;
  }
  check(same == 17, "C04", "C04 17/18 members are normalized-identical across builds");

  // ---- C02: effective coverage from buckets.tsv ---------------------------
  {
    std::ifstream bf("buckets.tsv");
    if (!bf) {
      check(false, "C02", "C02 cannot open buckets.tsv");
    } else {
      std::string line;
      std::getline(bf, line);  // header
      int total = 0, frag = 0, inb = 0, alias = 0, cold = 0, other = 0;
      while (std::getline(bf, line)) {
        if (line.size() < 3) continue;
        ++total;
        std::stringstream ls(line);
        std::string idx, addr, name, lines, bucket;
        std::getline(ls, idx, '\t');
        std::getline(ls, addr, '\t');
        std::getline(ls, name, '\t');
        std::getline(ls, lines, '\t');
        std::getline(ls, bucket, '\t');
        if (bucket == "fragment") ++frag;
        else if (bucket == "in_table") ++inb;
        else if (bucket == "alias") ++alias;
        else if (bucket == "cold") ++cold;
        else ++other;
      }
      check(total == 400, "C02", "C02 buckets cover 400 functions (got " + std::to_string(total) + ")");
      check(other == 0, "C02", "C02 no unclassified rows");
      check(inb == 18, "C02", "C02 in_table == 18");
      double eff = double(inb + alias + cold) / double(total - frag);
      check(eff >= 0.90, "C02", "C02 effective coverage >= 90%");
      std::printf("coverage: total=%d fragment=%d in_table=%d alias=%d cold=%d eff=%.4f\n",
                  total, frag, inb, alias, cold, eff);
    }
  }

  // ---- summary -------------------------------------------------------------
  std::printf("assertions=%d failures=%d\n", g_total, g_fail);
  std::printf("per-member:");
  for (auto& kv : g_per_member)
    if (kv.first[0] == 'M') std::printf(" %s=%d", kv.first.c_str(), kv.second);
  std::printf("\n");
  std::printf(g_fail == 0 ? "RESULT: PASS\n" : "RESULT: FAIL\n");
  return g_fail == 0 ? 0 : 1;
}
